'use client';

import { useEffect, useId, useRef, useState } from 'react';
import type { KeyboardEvent } from 'react';
import './product-gallery.css';

export interface ProductGalleryItem {
  id: string;
  src: string;
  alt: string;
  caption?: string;
  thumbnail?: string;
}

export interface ProductGalleryProps {
  items: ProductGalleryItem[];
  title?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  className?: string;
}

/** A manual product image gallery with thumbnails and a native image viewer. */
export function ProductGallery({ items, title = 'A closer look', defaultValue, onValueChange, className = '' }: ProductGalleryProps) {
  const [value, setValue] = useState(defaultValue ?? items[0]?.id ?? '');
  const [expanded, setExpanded] = useState(false);
  const viewer = useRef<HTMLDialogElement>(null);
  const opener = useRef<HTMLButtonElement>(null);
  const thumbnails = useRef(new Map<string, HTMLButtonElement>());
  const instance = useId();
  const headingId = `ac-product-title-${instance}`;
  const viewerId = `ac-product-viewer-${instance}`;
  const viewerTitleId = `${viewerId}-title`;
  const foundIndex = items.findIndex(item => item.id === value);
  const index = foundIndex < 0 ? 0 : foundIndex;
  const selected = items[index];
  const hasItems = items.length > 0;

  useEffect(() => {
    if (!expanded || !hasItems) return;
    const modal = viewer.current;
    if (!modal) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    if (!modal.open) modal.showModal();
    return () => {
      if (modal.open) modal.close();
      document.body.style.overflow = previousOverflow;
      opener.current?.focus({ preventScroll: true });
    };
  }, [expanded, hasItems]);

  function choose(nextIndex: number) {
    const next = items[(nextIndex + items.length) % items.length];
    if (!next || next.id === selected?.id) return;
    setValue(next.id);
    onValueChange?.(next.id);
  }

  function onThumbnailKey(event: KeyboardEvent<HTMLButtonElement>, currentIndex: number) {
    let nextIndex: number;
    if (event.key === 'ArrowRight') nextIndex = (currentIndex + 1) % items.length;
    else if (event.key === 'ArrowLeft') nextIndex = (currentIndex - 1 + items.length) % items.length;
    else if (event.key === 'Home') nextIndex = 0;
    else if (event.key === 'End') nextIndex = items.length - 1;
    else return;
    event.preventDefault();
    choose(nextIndex);
    thumbnails.current.get(items[nextIndex].id)?.focus({ preventScroll: true });
    thumbnails.current.get(items[nextIndex].id)?.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
  }

  return (
    <section className={`ac-product-gallery ${className}`.trim()} aria-labelledby={title ? headingId : undefined} aria-label={title ? undefined : 'Product images'}>
      {title && <header className="ac-product-gallery-heading"><span>IN THE DETAILS</span><h2 id={headingId}>{title}</h2></header>}
      {selected ? <>
        <figure className="ac-product-gallery-figure">
          <div className="ac-product-gallery-stage">
            <img key={selected.id} src={selected.src} alt={selected.alt} className="ac-product-gallery-image" />
            <button ref={opener} type="button" className="ac-product-gallery-expand" aria-label="Expand image" aria-haspopup="dialog" aria-controls={viewerId} aria-expanded={expanded} onClick={() => setExpanded(true)}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M9 4H4v5m11-5h5v5M4 15v5h5m11-5v5h-5" stroke="currentColor" strokeWidth="1.5" /></svg>
            </button>
          </div>
          {selected.caption && <figcaption>{selected.caption}</figcaption>}
        </figure>
        <div className="ac-product-gallery-controls">
          <span className="ac-product-gallery-count" aria-live="polite" aria-atomic="true">{String(index + 1).padStart(2, '0')} <span aria-hidden="true">/</span><span className="ac-product-gallery-sr"> of </span> {String(items.length).padStart(2, '0')}</span>
          <div className="ac-product-gallery-arrows"><button type="button" aria-label="Previous image" disabled={items.length < 2} onClick={() => choose(index - 1)}>←</button><button type="button" aria-label="Next image" disabled={items.length < 2} onClick={() => choose(index + 1)}>→</button></div>
        </div>
        <div className="ac-product-gallery-thumbnails" role="group" aria-label="Choose a product image">
          {items.map((item, itemIndex) => <button key={item.id} type="button" ref={element => { if (element) thumbnails.current.set(item.id, element); else thumbnails.current.delete(item.id); }} aria-label={`Show image ${itemIndex + 1}: ${item.alt}`} aria-pressed={item.id === selected.id} onClick={() => choose(itemIndex)} onKeyDown={event => onThumbnailKey(event, itemIndex)}><img src={item.thumbnail ?? item.src} alt="" loading="lazy" /></button>)}
        </div>
      </> : <p className="ac-product-gallery-empty">Product images will appear here.</p>}
      <dialog ref={viewer} id={viewerId} className="ac-product-gallery-dialog" aria-labelledby={viewerTitleId} onCancel={event => { event.preventDefault(); setExpanded(false); }} onClose={() => { if (!viewer.current?.open) setExpanded(false); }}>
        <header><h2 id={viewerTitleId}>{title || 'Product image'}</h2><button className="ac-product-gallery-close" type="button" onClick={() => setExpanded(false)}>Close <span aria-hidden="true">×</span></button></header>
        {selected && <><figure><img src={selected.src} alt={selected.alt} />{selected.caption && <figcaption>{selected.caption}</figcaption>}</figure><div className="ac-product-gallery-dialog-controls"><button type="button" aria-label="Previous image in viewer" disabled={items.length < 2} onClick={() => choose(index - 1)}>← <span>Previous</span></button><span aria-live="polite" aria-atomic="true">Image {index + 1} of {items.length}</span><button type="button" aria-label="Next image in viewer" disabled={items.length < 2} onClick={() => choose(index + 1)}><span>Next</span> →</button></div></>}
      </dialog>
    </section>
  );
}

.ac-product-gallery {
  --ac-product-surface: #eeeae0;
  --ac-product-stage: #e4dfd2;
  --ac-product-ink: #34382d;
  --ac-product-muted: #737768;
  --ac-product-line: #34382d33;
  --ac-product-accent: #52613f;
  container-type: inline-size;
  padding: 32px;
  background: var(--ac-product-surface);
  color: var(--ac-product-ink);
  font-family: inherit;
}
.ac-product-gallery, .ac-product-gallery::before, .ac-product-gallery::after, .ac-product-gallery *, .ac-product-gallery *::before, .ac-product-gallery *::after { box-sizing: border-box; }
.ac-product-gallery button { font: inherit; color: inherit; cursor: pointer; }
.ac-product-gallery button:focus-visible { outline: 2px solid var(--ac-product-accent); outline-offset: 4px; }
.ac-product-gallery button:disabled { opacity: .35; cursor: default; }
.ac-product-gallery-heading { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin-bottom: 20px; }
.ac-product-gallery-heading > span { font-size: 10px; letter-spacing: .12em; color: var(--ac-product-muted); }
.ac-product-gallery-heading h2 { margin: 0; font-size: clamp(24px, 5cqw, 42px); line-height: 1.05; letter-spacing: -.045em; font-weight: 500; }
.ac-product-gallery-figure { margin: 0; }
.ac-product-gallery-stage { position: relative; display: grid; place-items: center; height: clamp(240px, 55cqw, 500px); background: var(--ac-product-stage); overflow: hidden; }
.ac-product-gallery-image { width: 100%; height: 100%; min-height: 0; object-fit: contain; animation: ac-product-arrive .25s ease-out; }
.ac-product-gallery-expand { position: absolute; right: 13px; bottom: 13px; display: grid; place-items: center; width: 44px; height: 44px; border: 1px solid var(--ac-product-line); background: var(--ac-product-surface); border-radius: 50%; transition: background .15s, transform .15s; }
.ac-product-gallery-expand:hover { transform: scale(1.05); }
.ac-product-gallery-figure figcaption { margin-top: 12px; font-size: 13px; color: var(--ac-product-muted); line-height: 1.5; }
.ac-product-gallery-controls { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin: 8px 0 13px; }
.ac-product-gallery-count { display: flex; gap: 8px; font-size: 12px; font-variant-numeric: tabular-nums; }
.ac-product-gallery-count > span[aria-hidden] { color: var(--ac-product-muted); }
.ac-product-gallery-arrows { display: flex; gap: 5px; }
.ac-product-gallery-arrows button { min-width: 44px; min-height: 44px; font-size: 23px; border: 1px solid var(--ac-product-line); background: transparent; border-radius: 50%; }
.ac-product-gallery-arrows button:hover:not(:disabled) { background: var(--ac-product-stage); }
.ac-product-gallery-thumbnails { display: flex; gap: 9px; padding: 5px; margin: -5px; overflow-x: auto; scrollbar-width: thin; scroll-snap-type: x proximity; }
.ac-product-gallery-thumbnails button { flex: 0 0 78px; height: 72px; padding: 3px; border: 1px solid transparent; background: transparent; scroll-snap-align: start; }
.ac-product-gallery-thumbnails button[aria-pressed=true] { border-color: var(--ac-product-accent); }
.ac-product-gallery-thumbnails img { display: block; width: 100%; height: 100%; object-fit: contain; background: var(--ac-product-stage); }
.ac-product-gallery-empty { display: grid; place-items: center; min-height: 250px; color: var(--ac-product-muted); }
.ac-product-gallery-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.ac-product-gallery-dialog { width: min(1000px, calc(100vw - 28px)); max-width: none; max-height: 90dvh; padding: 24px; border: 1px solid var(--ac-product-line); background: var(--ac-product-surface); color: var(--ac-product-ink); font-family: inherit; overflow: auto; }
.ac-product-gallery-dialog:not([open]) { display: none; }
.ac-product-gallery-dialog[open] { display: flex; flex-direction: column; }
.ac-product-gallery-dialog::backdrop { background: #161a15bf; backdrop-filter: blur(5px); }
.ac-product-gallery-dialog > header { display: flex; flex-shrink: 0; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 15px; }
.ac-product-gallery-dialog h2 { margin: 0; font-size: clamp(20px, 3vw, 32px); font-weight: 500; letter-spacing: -.035em; }
.ac-product-gallery-close { display: flex; align-items: center; gap: 15px; min-height: 44px; padding: 6px 10px; border: 0; background: transparent; font-size: 13px!important; }
.ac-product-gallery-close span { font-size: 28px; line-height: 1; }
.ac-product-gallery-dialog figure { display: flex; flex-direction: column; min-height: 0; margin: 0; }
.ac-product-gallery-dialog figure > img { display: block; width: 100%; height: min(60dvh, 650px); min-height: 140px; object-fit: contain; background: var(--ac-product-stage); }
.ac-product-gallery-dialog figcaption { margin-top: 12px; font-size: 13px; line-height: 1.5; color: var(--ac-product-muted); }
.ac-product-gallery-dialog-controls { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: 15px; font-size: 12px; }
.ac-product-gallery-dialog-controls button { min-height: 44px; padding: 8px 13px; display: flex; align-items: center; gap: 12px; border: 1px solid var(--ac-product-line); background: transparent; }
@container (max-width: 450px) {
  .ac-product-gallery-heading { align-items: start; flex-direction: column; gap: 8px; }
  .ac-product-gallery-thumbnails button { flex-basis: 66px; height: 62px; }
}
@media (max-width: 480px) {
  .ac-product-gallery-dialog { padding: 16px; }
  .ac-product-gallery-dialog-controls button span { display: none; }
}
@keyframes ac-product-arrive { from { opacity: .4; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) {
  .ac-product-gallery-image { animation: none; }
  .ac-product-gallery-expand { transition: none; }
}
